1	/* claudinite.com — behavior. Vanilla JS, no dependencies.
2	   Jobs: reveal-on-scroll, the hero gates, the building, the ladder, the
3	   session terminal, the fleet board, the adopt typewriter, and rendering the
4	   promoted-content slots from data/promoted.js. Every figure is authored in
5	   its still frame in the markup; this file only moves things, and does not
6	   under prefers-reduced-motion. */
7	(function () {
8	  'use strict';
9	
10	  var REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
11	  var DATA = window.CLAUDINITE || null;
12	
13	  function el(tag, cls, text) {
14	    var n = document.createElement(tag);
15	    if (cls) n.className = cls;
16	    if (text !== undefined) n.textContent = text;
17	    return n;
18	  }
19	
20	  // Runs fn once, the first time node scrolls into view.
21	  function onceVisible(node, threshold, fn) {
22	    if (!('IntersectionObserver' in window)) { fn(); return; }
23	    var seen = false;
24	    var io = new IntersectionObserver(function (entries) {
25	      entries.forEach(function (e) {
26	        if (e.isIntersecting && !seen) { seen = true; fn(); io.disconnect(); }
27	      });
28	    }, { threshold: threshold });
29	    io.observe(node);
30	  }
31	
32	  /* ---------------------- reveal on scroll ---------------------- */
33	  var revealed = document.querySelectorAll('.reveal');
34	  if (REDUCED || !('IntersectionObserver' in window)) {
35	    revealed.forEach(function (n) { n.classList.add('in'); });
36	  } else {
37	    var ro = new IntersectionObserver(function (entries) {
38	      entries.forEach(function (e) {
39	        if (e.isIntersecting) { e.target.classList.add('in'); ro.unobserve(e.target); }
40	      });
41	    }, { threshold: 0.18 });
42	    revealed.forEach(function (n) { ro.observe(n); });
43	  }
44	
45	  /* --------------------- hero: the two gates ---------------------
46	     Three changes travel their lanes. One fails the Stop gate and goes back to
47	     its session with the fix; one fails the CI gate the same way; what passes
48	     both lands on main. Positions are the svg's own x coordinates. */
49	  (function gates() {
50	    var svg = document.getElementById('gates-viz');
51	    if (!svg || REDUCED) return;
52	
53	    var X = { session: 166, gate1: 392, gate2: 660, main: 788 };
54	    var LANES = [82, 180, 278];
55	    var chips = [1, 2, 3].map(function (i) { return document.getElementById('chip-' + i); });
56	    var tags = [document.getElementById('tag-1'), document.getElementById('tag-2')];
57	    var lamps = [document.querySelector('#gate-1 .gt-lamp'), document.querySelector('#gate-2 .gt-lamp')];
58	    var landed = Array.prototype.slice.call(svg.querySelectorAll('.gt-landed'));
59	    var timers = [];
60	    var slot = 0;
61	
62	    function at(ms, fn) { timers.push(setTimeout(fn, ms)); }
63	    function place(chip, x, lane, ms) {
64	      chip.style.transition = ms ? 'transform ' + ms + 'ms linear, opacity 0.3s ease' : 'opacity 0.3s ease';
65	      chip.style.transform = 'translate(' + x + 'px, ' + lane + 'px)';
66	    }
67	    function state(chip, cls) {
68	      chip.classList.remove('chip-bad'); chip.classList.remove('chip-good');
69	      if (cls) chip.classList.add(cls);
70	    }
71	    function lamp(i, cls) {
72	      lamps[i].classList.remove('bad'); lamps[i].classList.remove('good');
73	      if (cls) lamps[i].classList.add(cls);
74	    }
75	    function tag(i, on, lane) {
76	      tags[i].style.transform = 'translate(' + (i === 0 ? X.gate1 - 74 : X.gate2 - 74) + 'px, ' + lane + 'px)';
77	      tags[i].classList.toggle('on', on);
78	    }
79	    function land(chip) {
80	      chip.classList.remove('on');
81	      if (slot >= landed.length) { landed.forEach(function (r) { r.classList.remove('on'); }); slot = 0; }
82	      landed[slot++].classList.add('on');
83	    }
84	
85	    function reset() {
86	      timers.forEach(clearTimeout); timers = [];
87	      chips.forEach(function (c, i) { c.classList.remove('on'); state(c, null); place(c, X.session, LANES[i], 0); });
88	      tags.forEach(function (t) { t.classList.remove('on'); });
89	      lamp(0, null); lamp(1, null);
90	      if (slot === 0) landed.forEach(function (r) { r.classList.remove('on'); });
91	    }
92	
93	    // One change's trip: out to a gate, and either through or back.
94	    function travel(chip, lane, t0, failAt, done) {
95	      var t = t0;
96	      at(t, function () { chip.classList.add('on'); });
97	      at(t + 100, function () { place(chip, X.gate1, lane, 1300); }); t += 1500;
98	      if (failAt === 1) {
99	        at(t, function () { state(chip, 'chip-bad'); lamp(0, 'bad'); tag(0, true, lane); });
100	        at(t + 900, function () { place(chip, X.session, lane, 1100); lamp(0, null); }); t += 2100;
101	        at(t, function () { state(chip, null); tag(0, false, lane); });
102	        at(t + 500, function () { place(chip, X.gate1, lane, 1300); }); t += 1900;
103	      }
104	      at(t, function () { state(chip, 'chip-good'); lamp(0, 'good'); });
105	      at(t + 300, function () { place(chip, X.gate2, lane, 1200); lamp(0, null); }); t += 1600;
106	      if (failAt === 2) {
107	        at(t, function () { state(chip, 'chip-bad'); lamp(1, 'bad'); tag(1, true, lane); });
108	        at(t + 900, function () { place(chip, X.session, lane, 1900); lamp(1, null); }); t += 2900;
109	        at(t, function () { state(chip, null); tag(1, false, lane); });
110	        at(t + 500, function () { place(chip, X.gate1, lane, 1300); }); t += 1900;
111	        at(t, function () { state(chip, 'chip-good'); lamp(0, 'good'); });
112	        at(t + 300, function () { place(chip, X.gate2, lane, 1200); lamp(0, null); }); t += 1600;
113	      }
114	      at(t, function () { lamp(1, 'good'); });
115	      at(t + 300, function () { place(chip, X.main, lane, 700); lamp(1, null); }); t += 1100;
116	      at(t, function () { land(chip); });
117	      if (done) at(t + 1400, done);
118	      return t;
119	    }
120	
121	    function play() {
122	      reset();
123	      var end = 0;
124	      end = Math.max(end, travel(chips[0], LANES[0], 0, 1));
125	      end = Math.max(end, travel(chips[1], LANES[1], 900, 2));
126	      end = Math.max(end, travel(chips[2], LANES[2], 1800, 0));
127	      at(end + 1600, play);
128	    }
129	
130	    var replay = document.getElementById('gates-replay');
131	    if (replay) replay.addEventListener('click', play);
132	    onceVisible(svg, 0.25, play);
133	  })();
134	
135	  /* ------------------- the building settles ---------------------
136	     The markup is authored settled; dropping the class and putting it back
137	     runs the per-floor transitions in style.css. */
138	  (function building() {
139	    var svg = document.getElementById('building-viz');
140	    if (!svg || REDUCED) return;
141	
142	    function play() {
143	      svg.classList.remove('settled'); svg.classList.remove('pulse');
144	      void svg.getBoundingClientRect();
145	      svg.classList.add('settled'); svg.classList.add('pulse');
146	    }
147	
148	    var replay = document.getElementById('building-replay');
149	    if (replay) replay.addEventListener('click', play);
150	    svg.classList.remove('settled');
151	    onceVisible(svg, 0.35, play);
152	  })();
153	
154	  /* ---------------------- the ladder climbs ---------------------
155	     One rule token climbs from prose to setting; the meter drains beside it.
156	     The rungs' geometry is read live, so the token lands wherever the
157	     stylesheet put each tread at the current width. */
158	  (function ladder() {
159	    var box = document.getElementById('ladder');
160	    var token = document.getElementById('ladder-token');
161	    if (!box || !token) return;
162	    var rungs = Array.prototype.slice.call(box.querySelectorAll('.rung'));
163	    var timers = [];
164	
165	    function setRung(n) {
166	      for (var i = 0; i < rungs.length; i++) box.classList.remove('at-' + i);
167	      box.classList.add('at-' + n);
168	      var rung = rungs[n];
169	      var tread = rung.querySelector('.rung-tread');
170	      var x = rung.offsetLeft + tread.offsetLeft + tread.offsetWidth - token.offsetWidth + 6;
171	      var y = rung.offsetTop - token.offsetHeight / 2 + 1;
172	      token.style.transform = 'translate(' + x + 'px, ' + y + 'px)';
173	    }
174	
175	    if (REDUCED) { setRung(rungs.length - 1); window.addEventListener('resize', function () { setRung(rungs.length - 1); }); return; }
176	
177	    var current = rungs.length - 1;
178	    function play() {
179	      timers.forEach(clearTimeout); timers = [];
180	      rungs.forEach(function (r, i) {
181	        timers.push(setTimeout(function () { current = i; setRung(i); }, i * 1100));
182	      });
183	      timers.push(setTimeout(play, rungs.length * 1100 + 2600));
184	    }
185	    window.addEventListener('resize', function () { setRung(current); });
186	
187	    var replay = document.getElementById('ladder-replay');
188	    if (replay) replay.addEventListener('click', play);
189	    setRung(current);
190	    onceVisible(box, 0.4, play);
191	  })();
192	
193	  /* ------------------ session-loop terminal ---------------------- */
194	  (function sessionTerm() {
195	    var body = document.getElementById('term-body');
196	    if (!body) return;
197	    var lines = Array.prototype.slice.call(body.querySelectorAll('.t-line'));
198	    var timers = [];
199	
200	    function play() {
201	      timers.forEach(clearTimeout); timers = [];
202	      lines.forEach(function (l) { l.classList.remove('on'); });
203	      if (REDUCED) { lines.forEach(function (l) { l.classList.add('on'); }); return; }
204	      var t = 200;
205	      lines.forEach(function (l) {
206	        timers.push(setTimeout(function () { l.classList.add('on'); }, t));
207	        // linger on the failing check and its why/fix line, so the story reads
208	        var idx = Number(l.getAttribute('data-t'));
209	        t += (idx === 6 || idx === 7) ? 1100 : 480;
210	      });
211	    }
212	
213	    var replay = document.getElementById('term-replay');
214	    if (replay) replay.addEventListener('click', play);
215	    onceVisible(body, 0.35, play);
216	  })();
217	
218	  /* ------------------- fleet board: the daily update ------------- */
219	  (function fleetBoard() {
220	    var grid = document.getElementById('repo-grid');
221	    if (!grid) return;
222	    var names = ['payments', 'web-app', 'infra', 'ml-service', 'cli', 'docs-site', 'mobile', 'data-etl'];
223	    var REFS = ['e20584a', (DATA && DATA.canonRef) || '005edd2', '8b31f77'];
224	    var canonRefEl = document.getElementById('canon-ref');
225	    var pulse = document.getElementById('canon-pulse');
226	    var tiles = names.map(function (n) {
227	      var d = el('div', 'repo-tile');
228	      d.appendChild(el('span', 'r-name', n));
229	      d.appendChild(el('span', 'r-ref', REFS[0]));
230	      grid.appendChild(d);
231	      return d;
232	    });
233	
234	    var cur = 1; // canon starts one ref ahead of the fleet
235	    if (canonRefEl) canonRefEl.textContent = REFS[cur];
236	    if (REDUCED) {
237	      tiles.forEach(function (t) {
238	        t.classList.add('fresh');
239	        t.querySelector('.r-ref').textContent = REFS[cur];
240	      });
241	      return;
242	    }
243	    tiles.forEach(function (t) { t.classList.add('stale'); });
244	
245	    function update() {
246	      if (pulse) { pulse.classList.remove('go'); void pulse.offsetWidth; pulse.classList.add('go'); }
247	      tiles.forEach(function (t, i) {
248	        setTimeout(function () {
249	          t.classList.remove('stale');
250	          t.classList.add('fresh');
251	          t.querySelector('.r-ref').textContent = REFS[cur];
252	        }, 250 + i * 110);
253	      });
254	      // the canon moves on; the fleet is briefly behind again — that's the loop
255	      setTimeout(function () {
256	        cur = (cur + 1) % REFS.length;
257	        if (canonRefEl) canonRefEl.textContent = REFS[cur];
258	        tiles.forEach(function (t) { t.classList.remove('fresh'); t.classList.add('stale'); });
259	      }, 4600);
260	    }
261	    update();
262	    setInterval(update, 6400);
263	  })();
264	
265	  /* --------------------- adopt: typewriter ----------------------- */
266	  (function adoptType() {
267	    var target = document.getElementById('type-target');
268	    var result = document.getElementById('adopt-result');
269	    if (!target || !result) return;
270	    var TEXT = 'Adopt Claudinite — follow missingbulb/Claudinite’s bootstrap.md';
271	
272	    if (REDUCED) { target.textContent = TEXT; result.classList.add('on'); return; }
273	
274	    var started = false;
275	    function play() {
276	      if (started) return; started = true;
277	      var i = 0;
278	      (function step() {
279	        target.textContent = TEXT.slice(0, i);
280	        if (i <= TEXT.length) { i++; setTimeout(step, 26); }
281	        else setTimeout(function () { result.classList.add('on'); }, 350);
282	      })();
283	    }
284	    onceVisible(target, 0.4, play);
285	  })();
286	
287	  /* -------------- promoted-content slots (data-driven) ----------- */
288	  (function renderPromoted() {
289	    if (!DATA) return;
290	    try {
291	      var stats = document.getElementById('stats-slot');
292	      if (stats && DATA.stats) DATA.stats.forEach(function (s) {
293	        var d = el('div', 'stat');
294	        d.appendChild(el('b', null, s.n));
295	        d.appendChild(el('span', null, s.label));
296	        stats.appendChild(d);
297	      });
298	
299	      var spot = document.getElementById('spotlight-slot');
300	      if (spot && DATA.spotlight) DATA.spotlight.forEach(function (s) {
301	        var d = el('article', 'spot');
302	        d.appendChild(el('h3', null, s.title));
303	        d.appendChild(el('p', null, s.tag));
304	        spot.appendChild(d);
305	      });
306	
307	    } catch (err) {
308	      // A malformed promoted.js must never blank the page — evergreen sections
309	      // stand on their own; the canon link still gets people there.
310	      if (window.console) console.error('promoted-content render failed:', err);
311	    }
312	  })();
313	})();
314

