1	/* claudinite.com — design system.
2	   Palette: warm paper + ink monochrome, one malachite accent, semantic
3	   red/amber/green reserved for check states. Type: system grotesk + mono.
4	   Motion: reveal-on-scroll + mechanism loops, all gated by
5	   prefers-reduced-motion. No webfonts, no frameworks; the only external asset
6	   is the cookieless analytics beacon (see assets/analytics.js, privacy.html). */
7	
8	:root {
9	  --paper: #faf8f4;
10	  --paper-2: #f3f0e8;
11	  --ink: #16180f;
12	  --ink-soft: #5c6055;
13	  --line: #e4dfd2;
14	  --accent: #0e7c52;
15	  --accent-deep: #0a5c3e;
16	  --accent-wash: #e3efe6;
17	  --red: #c2402f;
18	  --red-wash: #f7e4e0;
19	  --amber: #b57816;
20	  --amber-wash: #f6ecd8;
21	  --term-bg: #141712;
22	  --radius: 14px;
23	  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;
24	  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
25	}
26	
27	* { box-sizing: border-box; margin: 0; padding: 0; }
28	html { scroll-behavior: smooth; }
29	body {
30	  font-family: var(--sans);
31	  background: var(--paper);
32	  color: var(--ink);
33	  line-height: 1.6;
34	  font-size: 17px;
35	  -webkit-font-smoothing: antialiased;
36	  text-rendering: optimizeLegibility;
37	}
38	
39	.wrap { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
40	.wrap-narrow { max-width: 780px; }
41	
42	h1, h2, h3 { line-height: 1.06; letter-spacing: -0.025em; font-weight: 700; text-wrap: balance; }
43	h1 { font-size: clamp(2.5rem, 5.6vw, 4.3rem); }
44	h2 { font-size: clamp(1.8rem, 3.6vw, 2.7rem); margin-bottom: 0.55em; }
45	h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
46	p { max-width: 62ch; }
47	code, .mono {
48	  font-family: var(--mono);
49	  font-size: 0.88em;
50	  background: var(--paper-2);
51	  border: 1px solid var(--line);
52	  border-radius: 5px;
53	  padding: 0.08em 0.35em;
54	  white-space: nowrap;
55	}
56	.mono b { color: var(--accent-deep); }
57	::selection { background: var(--accent); color: #fff; }
58	:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
59	
60	.skip {
61	  position: absolute; left: -9999px; top: 0;
62	  background: var(--ink); color: var(--paper); padding: 10px 16px; z-index: 99;
63	}
64	.skip:focus { left: 12px; top: 12px; }
65	
66	.eyebrow {
67	  font-family: var(--mono);
68	  font-size: 0.72rem;
69	  letter-spacing: 0.16em;
70	  text-transform: uppercase;
71	  color: var(--accent-deep);
72	  margin-bottom: 1.1em;
73	}
74	.eyebrow::before { content: "◆ "; font-size: 0.85em; }
75	
76	/* ------------------------------- nav ------------------------------- */
77	.nav {
78	  position: sticky; top: 0; z-index: 50;
79	  background: color-mix(in srgb, var(--paper) 88%, transparent);
80	  backdrop-filter: blur(10px);
81	  border-bottom: 1px solid var(--line);
82	}
83	.nav-inner {
84	  max-width: 1140px; margin: 0 auto; padding: 14px 24px;
85	  display: flex; align-items: center; justify-content: space-between; gap: 16px;
86	}
87	.brand {
88	  display: inline-flex; align-items: center; gap: 9px;
89	  font-family: var(--mono); font-weight: 700; font-size: 1.05rem;
90	  color: var(--ink); text-decoration: none; letter-spacing: -0.02em;
91	}
92	.brand-glyph { width: 22px; height: 22px; color: var(--accent); }
93	.nav nav { display: flex; align-items: center; gap: 22px; }
94	.nav nav a {
95	  color: var(--ink-soft); text-decoration: none; font-size: 0.92rem; font-weight: 550;
96	}
97	.nav nav a:hover { color: var(--ink); }
98	.nav-cta {
99	  color: #fff !important; background: var(--ink);
100	  padding: 7px 15px; border-radius: 999px;
101	}
102	.nav-cta:hover { background: var(--accent-deep); }
103	
104	/* ------------------------------ buttons ---------------------------- */
105	.btn {
106	  display: inline-block; text-decoration: none; font-weight: 620; font-size: 0.98rem;
107	  padding: 13px 24px; border-radius: 999px; border: 1.5px solid var(--ink);
108	  transition: transform 0.15s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
109	}
110	.btn:active { transform: translateY(1px); }
111	.btn-primary { background: var(--ink); color: var(--paper); }
112	.btn-primary:hover { background: var(--accent-deep); border-color: var(--accent-deep); box-shadow: 0 6px 24px -8px var(--accent-deep); }
113	.btn-ghost { color: var(--ink); background: transparent; }
114	.btn-ghost:hover { background: var(--paper-2); }
115	.cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 1.8em; }
116	
117	.replay {
118	  font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em;
119	  color: var(--ink-soft); background: none; border: 1px solid var(--line);
120	  border-radius: 999px; padding: 5px 14px; cursor: pointer;
121	}
122	.replay:hover { color: var(--ink); border-color: var(--ink-soft); }
123	
124	/* ------------------------------- hero ------------------------------ */
125	.hero { padding: clamp(36px, 5vw, 64px) 0 clamp(32px, 5vw, 56px); overflow: hidden; }
126	.hero-copy { max-width: 52rem; }
127	.lede { font-size: clamp(1.05rem, 1.7vw, 1.24rem); color: var(--ink-soft); margin-top: 1.2em; }
128	.lede-sm { font-size: 1.05rem; color: var(--ink-soft); }
129	.hero-fine { font-size: 0.85rem; color: var(--ink-soft); margin-top: 1.2em; font-family: var(--mono); }
130	h1 { margin-top: 0.2em; }
131	
132	.viz-caption {
133	  font-family: var(--mono); font-size: 0.72rem; color: var(--ink-soft);
134	  text-align: center; margin-top: 4px; letter-spacing: 0.06em;
135	}
136	.fig-caption {
137	  display: flex; align-items: center; justify-content: center;
138	  gap: 14px; flex-wrap: wrap; margin-top: 12px;
139	}
140	
141	/* Shared vocabulary of every drawn figure: low-opacity ink strokes, mono
142	   labels, one accent. */
143	.fig { margin: 0; }
144	.fig svg { width: 100%; height: auto; display: block; overflow: visible; }
145	.fig text, .gates-viz text { font-family: var(--mono); fill: var(--ink-soft); }
146	
147	/* ------------------------- the two gates (hero) -------------------- */
148	.gates { margin: clamp(28px, 4vw, 48px) auto 0; max-width: 1040px; }
149	.gates-viz { width: 100%; height: auto; display: block; overflow: visible; }
150	.gt-lanes path { stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 2 7; opacity: 0.3; fill: none; }
151	.gt-term rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; opacity: 0.55; }
152	.gt-term-bar { stroke: var(--ink); stroke-width: 1; opacity: 0.35; fill: none; }
153	.gt-term circle { fill: var(--ink); opacity: 0.35; }
154	.gt-term text { font-size: 11px; letter-spacing: 0.08em; }
155	.gt-code { stroke: var(--ink-soft); stroke-width: 2.2; stroke-linecap: round; opacity: 0.4; fill: none; }
156	.gt-gate rect { fill: var(--paper-2); stroke: var(--ink); stroke-width: 1.4; opacity: 0.8; }
157	.gt-gate-name { font-size: 14px; font-weight: 700; fill: var(--ink); text-anchor: middle; }
158	.gt-gate-note { font-size: 12px; text-anchor: middle; letter-spacing: 0.02em; }
159	.gt-lamp { fill: var(--paper); stroke: var(--ink); stroke-width: 1.2; transition: fill 0.25s ease, stroke 0.25s ease; }
160	.gt-lamp.bad { fill: var(--red); stroke: var(--red); }
161	.gt-lamp.good { fill: var(--accent); stroke: var(--accent); }
162	.gt-main rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.6; }
163	.gt-main-bar { stroke: var(--ink); stroke-width: 1; opacity: 0.35; fill: none; }
164	.gt-main text { font-size: 14px; font-weight: 700; fill: var(--ink); text-anchor: middle; }
165	.gt-landed { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.2; opacity: 0; transition: opacity 0.3s ease; }
166	.gt-landed.on { opacity: 1; }
167	.gt-chip { opacity: 0; transition: opacity 0.3s ease; }
168	.gt-chip.on { opacity: 1; }
169	.gt-chip rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.5; transition: fill 0.25s ease, stroke 0.25s ease; }
170	.gt-chip path { stroke: var(--ink); stroke-width: 1.5; stroke-linecap: round; fill: none; opacity: 0.6; transition: stroke 0.25s ease; }
171	.gt-chip.chip-bad rect { fill: var(--red-wash); stroke: var(--red); }
172	.gt-chip.chip-bad path { stroke: var(--red); }
173	.gt-chip.chip-good rect { fill: var(--accent-wash); stroke: var(--accent); }
174	.gt-chip.chip-good path { stroke: var(--accent-deep); }
175	.gt-tag { opacity: 0; transition: opacity 0.25s ease; }
176	.gt-tag.on { opacity: 1; }
177	.gt-tag rect { fill: var(--red-wash); stroke: var(--red); stroke-width: 1.2; }
178	.gt-tag text { font-size: 11.5px; fill: var(--red); text-anchor: middle; font-weight: 700; }
