180	/* ------------------------------ quote ------------------------------ */
181	.quote-band { border-top: 1px solid var(--line); background: var(--paper-2); padding: clamp(36px, 5vw, 56px) 0; }
182	.quote { padding-left: clamp(14px, 2vw, 22px); border-left: 3px solid var(--accent); max-width: 60rem; }
183	.quote p {
184	  font-size: clamp(1.35rem, 2.8vw, 2rem); line-height: 1.22;
185	  letter-spacing: -0.02em; font-weight: 600; max-width: 30ch;
186	}
187	.quote cite { display: block; margin-top: 0.7em; font-style: normal; font-size: 0.88rem; color: var(--ink-soft); }
188	.quote cite a { color: inherit; }
