190	/* --------------------------- mechanism grid ------------------------ */
191	.mech { padding: clamp(56px, 8vw, 104px) 0; border-top: 1px solid var(--line); }
192	.mech-grid {
193	  display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
194	  gap: clamp(32px, 6vw, 80px); align-items: center;
195	}
196	.mech-grid-flip > .mech-copy { order: 2; }
197	.mech-points { margin: 1.4em 0 0 1.1em; display: grid; gap: 0.55em; color: var(--ink-soft); }
198	.mech-points li::marker { color: var(--accent); }
199	.mech-points strong { color: var(--ink); }
200	.mech-fine { font-size: 0.88rem; color: var(--ink-soft); margin-top: 1.2em; }
201	.kicker { margin-top: 1.6em; font-size: clamp(1.1rem, 2vw, 1.3rem); letter-spacing: -0.01em; color: var(--accent-deep); font-weight: 600; }
202	.mech-band { background: var(--paper-2); }
203	
204	/* ------------------------- the building (gap) ---------------------- */
205	.bf-floor rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; opacity: 0.45; }
206	.bf-floor-3 rect, .bf-floor-1 rect { fill: var(--paper-2); }
207	.bf-q { font-size: 14px; font-weight: 700; fill: var(--ink); }
208	.bf-note { font-size: 12.5px; }
209	.bf-ground rect { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.8; }
210	.bf-ground .bf-q, .bf-ground .bf-note { fill: var(--accent-deep); }
211	.bf-stamp rect { fill: none; stroke: var(--accent-deep); stroke-width: 1.5; }
212	.bf-stamp text { font-size: 11.5px; letter-spacing: 0.1em; text-transform: uppercase; fill: var(--accent-deep); text-anchor: middle; font-weight: 700; }
213	.bf-earth { stroke: var(--ink); stroke-width: 2; fill: none; }
214	.bf-hatch { stroke: var(--ink); stroke-width: 1.2; opacity: 0.35; fill: none; }
215	/* Floors drop in once .settled lands on the svg; each one waits for the floor below. */
216	.bf-floor { transition: transform 0.55s cubic-bezier(0.2, 0.7, 0.2, 1), opacity 0.4s ease; }
217	.building:not(.settled) .bf-floor { transform: translateY(-40px); opacity: 0; transition: none; }
218	.building.settled .bf-floor-1 { transition-delay: 0.1s; }
219	.building.settled .bf-floor-2 { transition-delay: 0.5s; }
220	.building.settled .bf-floor-3 { transition-delay: 0.9s; }
221	.building.settled .bf-floor-4 { transition-delay: 1.3s; }
222	.bf-stamp { transform-box: fill-box; transform-origin: center; }
223	.building.settled.pulse .bf-stamp { animation: stamp 0.7s ease 1.9s 1; }
224	@keyframes stamp { 0%, 100% { transform: scale(1); } 40% { transform: scale(1.14); } }
225	
226	/* ---------------------------- the ladder --------------------------- */
227	.ladder { position: relative; padding-right: 64px; }
228	.ladder-steps { list-style: none; display: flex; flex-direction: column-reverse; gap: 0; }
229	.rung {
230	  position: relative; display: grid; grid-template-columns: 5rem 1fr; column-gap: 12px; align-items: center;
231	  padding: 11px 0 11px calc(2.6rem * var(--n) + 3.6rem); min-height: 64px;
232	}
233	.rung[data-rung="0"] { --n: 0; }
234	.rung[data-rung="1"] { --n: 1; }
235	.rung[data-rung="2"] { --n: 2; }
236	.rung[data-rung="3"] { --n: 3; }
237	.rung[data-rung="4"] { --n: 4; }
238	/* The tread is the step itself: it fills the rung's left, so the rungs stack into a staircase. */
239	.rung-tread {
240	  position: absolute; left: 0; top: 0; bottom: 0; width: calc(2.6rem * var(--n) + 2.6rem);
241	  background: var(--paper-2); border-top: 2px solid var(--ink); border-right: 2px solid var(--ink);
242	  transition: background 0.3s ease;
243	}
244	.rung[data-rung="0"] .rung-tread { border-bottom: 2px solid var(--ink); }
245	.rung-name { font-family: var(--mono); font-weight: 700; font-size: 0.98rem; color: var(--ink); }
246	.rung-meta { font-family: var(--mono); font-size: 0.78rem; line-height: 1.45; color: var(--ink-soft); display: grid; }
247	.rung-force { color: var(--ink); }
248	.at-0 .rung[data-rung="0"] .rung-tread, .at-1 .rung[data-rung="1"] .rung-tread, .at-2 .rung[data-rung="2"] .rung-tread,
249	.at-3 .rung[data-rung="3"] .rung-tread, .at-4 .rung[data-rung="4"] .rung-tread {
250	  background: var(--accent-wash); border-color: var(--accent-deep);
251	}
252	.at-0 .rung[data-rung="0"] .rung-name, .at-1 .rung[data-rung="1"] .rung-name, .at-2 .rung[data-rung="2"] .rung-name,
253	.at-3 .rung[data-rung="3"] .rung-name, .at-4 .rung[data-rung="4"] .rung-name { color: var(--accent-deep); }
254	.token {
255	  position: absolute; left: 0; top: 0; z-index: 2;
256	  font-family: var(--mono); font-size: 0.7rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
257	  background: var(--ink); color: var(--paper); border-radius: 999px; padding: 3px 10px;
258	  transform: translate(-9999px, 0); transition: transform 0.55s cubic-bezier(0.2, 0.7, 0.2, 1);
259	}
260	.meter {
261	  position: absolute; right: 0; top: 0; bottom: 0; width: 48px;
262	  display: flex; flex-direction: column; align-items: center; gap: 8px;
263	}
264	.meter-track { flex: 1; width: 16px; border: 1.5px solid var(--ink); border-radius: 8px; position: relative; overflow: hidden; background: var(--paper); }
265	.meter-fill {
266	  position: absolute; left: 0; right: 0; bottom: 0; height: 0; background: var(--amber);
267	  transition: height 0.6s ease;
268	}
269	.meter-label { font-family: var(--mono); font-size: 0.62rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-soft); }
270	.at-0 .meter-fill { height: 100%; }
271	.at-1 .meter-fill { height: 45%; }
272	
273	/* -------------------------- the growth ring ------------------------ */
274	.ring-fig svg { max-width: 480px; margin: 0 auto; }
275	.gr-arcs path { fill: none; stroke: var(--ink); stroke-width: 1.6; opacity: 0.45; marker-end: url(#gr-arrow); }
276	#gr-arrow path { fill: var(--ink); opacity: 0.6; }
277	.gr-pulse {
278	  fill: none; stroke: var(--accent); stroke-width: 4; stroke-linecap: round;
279	  stroke-dasharray: 34 1160; animation: gr-flow 9s linear infinite;
280	}
281	@keyframes gr-flow { to { stroke-dashoffset: -1194; } }
282	.gr-node circle { fill: var(--paper); stroke: var(--ink); stroke-width: 1.8; }
283	.gr-node text { font-size: 14.5px; fill: var(--ink); }
284	.gr-canon circle { fill: var(--accent); stroke: var(--accent-deep); }
285	.gr-canon text { fill: var(--accent-deep); font-weight: 700; }
286	.gr-center { font-size: 13px; letter-spacing: 0.08em; }
