288	/* ---------------------------- the data flow ------------------------ */
289	.flow-fig svg { max-width: 560px; margin: 0 auto; }
290	.df-box rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.5; opacity: 0.9; }
291	.df-repo rect { stroke-width: 1.8; opacity: 1; }
292	.df-name { font-size: 15px; font-weight: 700; fill: var(--ink); }
293	.df-sub { font-size: 12.5px; }
294	.df-file { font-size: 13px; }
295	.df-rule { stroke: var(--ink); stroke-width: 1; opacity: 0.25; }
296	.df-canon rect { fill: var(--accent-wash); stroke: var(--accent-deep); }
297	.df-canon .df-name, .df-canon .df-sub { fill: var(--accent-deep); }
298	.df-arrow { fill: none; stroke: var(--ink); stroke-width: 1.6; opacity: 0.6; marker-end: url(#df-arrow); }
299	.df-dashed { stroke-dasharray: 6 5; }
300	#df-arrow path { fill: var(--ink); opacity: 0.7; }
