502	  .repo-grid { grid-template-columns: repeat(2, 1fr); }
503	  .nav nav a:not(.nav-cta) { display: none; }
504	}
505	
506	/* SVG text scales with the viewBox, so on a narrow screen a figure's labels
507	   shrink below reading size. Enlarge them in user units where the drawing has
508	   room; hide the two that do not. */
509	@media (max-width: 720px) {
510	  .gates, .flow-fig { display: none; }
511	  .bf-q { font-size: 18px; }
512	  .bf-note { font-size: 16px; }
513	  .bf-stamp text { font-size: 14px; }
514	  .gr-node text { font-size: 20px; }
515	  .gr-center { font-size: 17px; }
516	  .ladder { padding-right: 56px; }
517	  .rung { grid-template-columns: 1fr; row-gap: 2px; padding-left: calc(1.3rem * var(--n) + 2.2rem); min-height: 72px; }
518	  .rung-tread { width: calc(1.3rem * var(--n) + 1.4rem); }
519	}
520	@media (max-width: 480px) {
521	  .repo-grid { grid-template-columns: repeat(2, 1fr); }
522	  .stats { grid-template-columns: 1fr 1fr; }
523	}
524	
525	/* -------------------------- reduced motion ------------------------- */
526	@media (prefers-reduced-motion: reduce) {
527	  html { scroll-behavior: auto; }
528	  .reveal, #term-body .t-line { opacity: 1; transform: none; transition: none; }
529	  .adopt-result { opacity: 1; }
530	  .caret, .clock-hand, .gr-pulse, .canon-pulse, .bf-stamp { animation: none !important; }
531	  .gt-chip, .gt-tag, .gt-landed, .gt-lamp, .gt-chip rect, .gt-chip path,
532	  .bf-floor, .token, .meter-fill, .rung-tread, .btn { transition: none !important; }
533	  .gr-pulse { stroke-dasharray: none; stroke: none; }
534	}
535	
536	/* ---------- Legal pages (privacy) ---------- */
537	.legal { padding: 72px 0 40px; }
538	.legal-title { font-size: clamp(2.2rem, 5vw, 3.4rem); margin-bottom: 0.4em; }
539	.legal-lede { font-size: 1.15rem; color: var(--ink-soft); margin-bottom: 1.6em; }
540	.legal p { margin-bottom: 1.1em; }
541	.legal h2 { font-size: clamp(1.3rem, 2.4vw, 1.7rem); margin: 1.8em 0 0.5em; }
542	.legal a { color: var(--accent-deep); }
543

file.content:
/* claudinite.com — design system.
   Palette: warm paper + ink monochrome, one malachite accent, semantic
   red/amber/green reserved for check states. Type: system grotesk + mono.
   Motion: reveal-on-scroll + mechanism loops, all gated by
   prefers-reduced-motion. No webfonts, no frameworks; the only external asset
   is the cookieless analytics beacon (see assets/analytics.js, privacy.html). */

:root {
  --paper: #faf8f4;
  --paper-2: #f3f0e8;
  --ink: #16180f;
  --ink-soft: #5c6055;
  --line: #e4dfd2;
  --accent: #0e7c52;
  --accent-deep: #0a5c3e;
  --accent-wash: #e3efe6;
  --red: #c2402f;
  --red-wash: #f7e4e0;
  --amber: #b57816;
  --amber-wash: #f6ecd8;
  --term-bg: #141712;
  --radius: 14px;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--sans);
  background: var(--paper);
  color: var(--ink);
  line-height: 1.6;
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.wrap { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
.wrap-narrow { max-width: 780px; }

h1, h2, h3 { line-height: 1.06; letter-spacing: -0.025em; font-weight: 700; text-wrap: balance; }
h1 { font-size: clamp(2.5rem, 5.6vw, 4.3rem); }
h2 { font-size: clamp(1.8rem, 3.6vw, 2.7rem); margin-bottom: 0.55em; }
h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
p { max-width: 62ch; }
code, .mono {
  font-family: var(--mono);
  font-size: 0.88em;
  background: var(--paper-2);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 0.08em 0.35em;
  white-space: nowrap;
}
.mono b { color: var(--accent-deep); }
::selection { background: var(--accent); color: #fff; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.skip {
  position: absolute; left: -9999px; top: 0;
  background: var(--ink); color: var(--paper); padding: 10px 16px; z-index: 99;
}
.skip:focus { left: 12px; top: 12px; }

.eyebrow {
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent-deep);
  margin-bottom: 1.1em;
}
.eyebrow::before { content: "◆ "; font-size: 0.85em; }

/* ------------------------------- nav ------------------------------- */
.nav {
  position: sticky; top: 0; z-index: 50;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.nav-inner {
  max-width: 1140px; margin: 0 auto; padding: 14px 24px;
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
}
.brand {
  display: inline-flex; align-items: center; gap: 9px;
  font-family: var(--mono); font-weight: 700; font-size: 1.05rem;
  color: var(--ink); text-decoration: none; letter-spacing: -0.02em;
}
.brand-glyph { width: 22px; height: 22px; color: var(--accent); }
.nav nav { display: flex; align-items: center; gap: 22px; }
.nav nav a {
  color: var(--ink-soft); text-decoration: none; font-size: 0.92rem; font-weight: 550;
}
.nav nav a:hover { color: var(--ink); }
.nav-cta {
  color: #fff !important; background: var(--ink);
  padding: 7px 15px; border-radius: 999px;
}
.nav-cta:hover { background: var(--accent-deep); }

/* ------------------------------ buttons ---------------------------- */
.btn {
  display: inline-block; text-decoration: none; font-weight: 620; font-size: 0.98rem;
  padding: 13px 24px; border-radius: 999px; border: 1.5px solid var(--ink);
  transition: transform 0.15s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--ink); color: var(--paper); }
.btn-primary:hover { background: var(--accent-deep); border-color: var(--accent-deep); box-shadow: 0 6px 24px -8px var(--accent-deep); }
.btn-ghost { color: var(--ink); background: transparent; }
.btn-ghost:hover { background: var(--paper-2); }
.cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 1.8em; }

.replay {
  font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em;
  color: var(--ink-soft); background: none; border: 1px solid var(--line);
  border-radius: 999px; padding: 5px 14px; cursor: pointer;
}
.replay:hover { color: var(--ink); border-color: var(--ink-soft); }

/* ------------------------------- hero ------------------------------ */
.hero { padding: clamp(36px, 5vw, 64px) 0 clamp(32px, 5vw, 56px); overflow: hidden; }
.hero-copy { max-width: 52rem; }
.lede { font-size: clamp(1.05rem, 1.7vw, 1.24rem); color: var(--ink-soft); margin-top: 1.2em; }
.lede-sm { font-size: 1.05rem; color: var(--ink-soft); }
.hero-fine { font-size: 0.85rem; color: var(--ink-soft); margin-top: 1.2em; font-family: var(--mono); }
h1 { margin-top: 0.2em; }

.viz-caption {
  font-family: var(--mono); font-size: 0.72rem; color: var(--ink-soft);
  text-align: center; margin-top: 4px; letter-spacing: 0.06em;
}
.fig-caption {
  display: flex; align-items: center; justify-content: center;
  gap: 14px; flex-wrap: wrap; margin-top: 12px;
}

/* Shared vocabulary of every drawn figure: low-opacity ink strokes, mono
   labels, one accent. */
.fig { margin: 0; }
.fig svg { width: 100%; height: auto; display: block; overflow: visible; }
.fig text, .gates-viz text { font-family: var(--mono); fill: var(--ink-soft); }

/* ------------------------- the two gates (hero) -------------------- */
.gates { margin: clamp(28px, 4vw, 48px) auto 0; max-width: 1040px; }
.gates-viz { width: 100%; height: auto; display: block; overflow: visible; }
.gt-lanes path { stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 2 7; opacity: 0.3; fill: none; }
.gt-term rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; opacity: 0.55; }
.gt-term-bar { stroke: var(--ink); stroke-width: 1; opacity: 0.35; fill: none; }
.gt-term circle { fill: var(--ink); opacity: 0.35; }
.gt-term text { font-size: 11px; letter-spacing: 0.08em; }
.gt-code { stroke: var(--ink-soft); stroke-width: 2.2; stroke-linecap: round; opacity: 0.4; fill: none; }
.gt-gate rect { fill: var(--paper-2); stroke: var(--ink); stroke-width: 1.4; opacity: 0.8; }
.gt-gate-name { font-size: 14px; font-weight: 700; fill: var(--ink); text-anchor: middle; }
.gt-gate-note { font-size: 12px; text-anchor: middle; letter-spacing: 0.02em; }
.gt-lamp { fill: var(--paper); stroke: var(--ink); stroke-width: 1.2; transition: fill 0.25s ease, stroke 0.25s ease; }
.gt-lamp.bad { fill: var(--red); stroke: var(--red); }
.gt-lamp.good { fill: var(--accent); stroke: var(--accent); }
.gt-main rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.6; }
.gt-main-bar { stroke: var(--ink); stroke-width: 1; opacity: 0.35; fill: none; }
.gt-main text { font-size: 14px; font-weight: 700; fill: var(--ink); text-anchor: middle; }
.gt-landed { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.2; opacity: 0; transition: opacity 0.3s ease; }
.gt-landed.on { opacity: 1; }
.gt-chip { opacity: 0; transition: opacity 0.3s ease; }
.gt-chip.on { opacity: 1; }
.gt-chip rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.5; transition: fill 0.25s ease, stroke 0.25s ease; }
.gt-chip path { stroke: var(--ink); stroke-width: 1.5; stroke-linecap: round; fill: none; opacity: 0.6; transition: stroke 0.25s ease; }
.gt-chip.chip-bad rect { fill: var(--red-wash); stroke: var(--red); }
.gt-chip.chip-bad path { stroke: var(--red); }
.gt-chip.chip-good rect { fill: var(--accent-wash); stroke: var(--accent); }
.gt-chip.chip-good path { stroke: var(--accent-deep); }
.gt-tag { opacity: 0; transition: opacity 0.25s ease; }
.gt-tag.on { opacity: 1; }
.gt-tag rect { fill: var(--red-wash); stroke: var(--red); stroke-width: 1.2; }
.gt-tag text { font-size: 11.5px; fill: var(--red); text-anchor: middle; font-weight: 700; }

/* ------------------------------ quote ------------------------------ */
.quote-band { border-top: 1px solid var(--line); background: var(--paper-2); padding: clamp(36px, 5vw, 56px) 0; }
.quote { padding-left: clamp(14px, 2vw, 22px); border-left: 3px solid var(--accent); max-width: 60rem; }
.quote p {
  font-size: clamp(1.35rem, 2.8vw, 2rem); line-height: 1.22;
  letter-spacing: -0.02em; font-weight: 600; max-width: 30ch;
}
.quote cite { display: block; margin-top: 0.7em; font-style: normal; font-size: 0.88rem; color: var(--ink-soft); }
.quote cite a { color: inherit; }

/* --------------------------- mechanism grid ------------------------ */
.mech { padding: clamp(56px, 8vw, 104px) 0; border-top: 1px solid var(--line); }
.mech-grid {
  display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: clamp(32px, 6vw, 80px); align-items: center;
}
.mech-grid-flip > .mech-copy { order: 2; }
.mech-points { margin: 1.4em 0 0 1.1em; display: grid; gap: 0.55em; color: var(--ink-soft); }
.mech-points li::marker { color: var(--accent); }
.mech-points strong { color: var(--ink); }
.mech-fine { font-size: 0.88rem; color: var(--ink-soft); margin-top: 1.2em; }
.kicker { margin-top: 1.6em; font-size: clamp(1.1rem, 2vw, 1.3rem); letter-spacing: -0.01em; color: var(--accent-deep); font-weight: 600; }
.mech-band { background: var(--paper-2); }

/* ------------------------- the building (gap) ---------------------- */
.bf-floor rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; opacity: 0.45; }
.bf-floor-3 rect, .bf-floor-1 rect { fill: var(--paper-2); }
.bf-q { font-size: 14px; font-weight: 700; fill: var(--ink); }
.bf-note { font-size: 12.5px; }
.bf-ground rect { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.8; }
.bf-ground .bf-q, .bf-ground .bf-note { fill: var(--accent-deep); }
.bf-stamp rect { fill: none; stroke: var(--accent-deep); stroke-width: 1.5; }
.bf-stamp text { font-size: 11.5px; letter-spacing: 0.1em; text-transform: uppercase; fill: var(--accent-deep); text-anchor: middle; font-weight: 700; }
.bf-earth { stroke: var(--ink); stroke-width: 2; fill: none; }
.bf-hatch { stroke: var(--ink); stroke-width: 1.2; opacity: 0.35; fill: none; }
/* Floors drop in once .settled lands on the svg; each one waits for the floor below. */
.bf-floor { transition: transform 0.55s cubic-bezier(0.2, 0.7, 0.2, 1), opacity 0.4s ease; }
.building:not(.settled) .bf-floor { transform: translateY(-40px); opacity: 0; transition: none; }
.building.settled .bf-floor-1 { transition-delay: 0.1s; }
.building.settled .bf-floor-2 { transition-delay: 0.5s; }
.building.settled .bf-floor-3 { transition-delay: 0.9s; }
.building.settled .bf-floor-4 { transition-delay: 1.3s; }
.bf-stamp { transform-box: fill-box; transform-origin: center; }
.building.settled.pulse .bf-stamp { animation: stamp 0.7s ease 1.9s 1; }
@keyframes stamp { 0%, 100% { transform: scale(1); } 40% { transform: scale(1.14); } }

/* ---------------------------- the ladder --------------------------- */
.ladder { position: relative; padding-right: 64px; }
.ladder-steps { list-style: none; display: flex; flex-direction: column-reverse; gap: 0; }
.rung {
  position: relative; display: grid; grid-template-columns: 5rem 1fr; column-gap: 12px; align-items: center;
  padding: 11px 0 11px calc(2.6rem * var(--n) + 3.6rem); min-height: 64px;
}
.rung[data-rung="0"] { --n: 0; }
.rung[data-rung="1"] { --n: 1; }
.rung[data-rung="2"] { --n: 2; }
.rung[data-rung="3"] { --n: 3; }
.rung[data-rung="4"] { --n: 4; }
/* The tread is the step itself: it fills the rung's left, so the rungs stack into a staircase. */
.rung-tread {
  position: absolute; left: 0; top: 0; bottom: 0; width: calc(2.6rem * var(--n) + 2.6rem);
  background: var(--paper-2); border-top: 2px solid var(--ink); border-right: 2px solid var(--ink);
  transition: background 0.3s ease;
}
.rung[data-rung="0"] .rung-tread { border-bottom: 2px solid var(--ink); }
.rung-name { font-family: var(--mono); font-weight: 700; font-size: 0.98rem; color: var(--ink); }
.rung-meta { font-family: var(--mono); font-size: 0.78rem; line-height: 1.45; color: var(--ink-soft); display: grid; }
.rung-force { color: var(--ink); }
.at-0 .rung[data-rung="0"] .rung-tread, .at-1 .rung[data-rung="1"] .rung-tread, .at-2 .rung[data-rung="2"] .rung-tread,
.at-3 .rung[data-rung="3"] .rung-tread, .at-4 .rung[data-rung="4"] .rung-tread {
  background: var(--accent-wash); border-color: var(--accent-deep);
}
.at-0 .rung[data-rung="0"] .rung-name, .at-1 .rung[data-rung="1"] .rung-name, .at-2 .rung[data-rung="2"] .rung-name,
.at-3 .rung[data-rung="3"] .rung-name, .at-4 .rung[data-rung="4"] .rung-name { color: var(--accent-deep); }
.token {
  position: absolute; left: 0; top: 0; z-index: 2;
  font-family: var(--mono); font-size: 0.7rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
  background: var(--ink); color: var(--paper); border-radius: 999px; padding: 3px 10px;
  transform: translate(-9999px, 0); transition: transform 0.55s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.meter {
  position: absolute; right: 0; top: 0; bottom: 0; width: 48px;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
}
.meter-track { flex: 1; width: 16px; border: 1.5px solid var(--ink); border-radius: 8px; position: relative; overflow: hidden; background: var(--paper); }
.meter-fill {
  position: absolute; left: 0; right: 0; bottom: 0; height: 0; background: var(--amber);
  transition: height 0.6s ease;
}
.meter-label { font-family: var(--mono); font-size: 0.62rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-soft); }
.at-0 .meter-fill { height: 100%; }
.at-1 .meter-fill { height: 45%; }

/* -------------------------- the growth ring ------------------------ */
.ring-fig svg { max-width: 480px; margin: 0 auto; }
.gr-arcs path { fill: none; stroke: var(--ink); stroke-width: 1.6; opacity: 0.45; marker-end: url(#gr-arrow); }
#gr-arrow path { fill: var(--ink); opacity: 0.6; }
.gr-pulse {
  fill: none; stroke: var(--accent); stroke-width: 4; stroke-linecap: round;
  stroke-dasharray: 34 1160; animation: gr-flow 9s linear infinite;
}
@keyframes gr-flow { to { stroke-dashoffset: -1194; } }
.gr-node circle { fill: var(--paper); stroke: var(--ink); stroke-width: 1.8; }
.gr-node text { font-size: 14.5px; fill: var(--ink); }
.gr-canon circle { fill: var(--accent); stroke: var(--accent-deep); }
.gr-canon text { fill: var(--accent-deep); font-weight: 700; }
.gr-center { font-size: 13px; letter-spacing: 0.08em; }

/* ---------------------------- the data flow ------------------------ */
.flow-fig svg { max-width: 560px; margin: 0 auto; }
.df-box rect { fill: var(--paper); stroke: var(--ink); stroke-width: 1.5; opacity: 0.9; }
.df-repo rect { stroke-width: 1.8; opacity: 1; }
.df-name { font-size: 15px; font-weight: 700; fill: var(--ink); }
.df-sub { font-size: 12.5px; }
.df-file { font-size: 13px; }
.df-rule { stroke: var(--ink); stroke-width: 1; opacity: 0.25; }
.df-canon rect { fill: var(--accent-wash); stroke: var(--accent-deep); }
.df-canon .df-name, .df-canon .df-sub { fill: var(--accent-deep); }
.df-arrow { fill: none; stroke: var(--ink); stroke-width: 1.6; opacity: 0.6; marker-end: url(#df-arrow); }
.df-dashed { stroke-dasharray: 6 5; }
#df-arrow path { fill: var(--ink); opacity: 0.7; }
.df-label { font-size: 12.5px; letter-spacing: 0.02em; }
.df-ghost rect { fill: none; stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 4 5; opacity: 0.35; }
.df-ghost text { font-size: 12.5px; opacity: 0.8; }

/* ----------------------------- pack stack -------------------------- */
.pack-stack { display: grid; gap: 14px; perspective: 900px; }
.pack-layer {
  background: var(--paper); border: 1.5px solid var(--ink); border-radius: var(--radius);
  padding: 18px 20px; box-shadow: 0 2px 0 var(--ink);
}
.pack-layer-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.file { font-family: var(--mono); font-weight: 700; font-size: 0.98rem; }
.pill {
  font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.08em; text-transform: uppercase;
  background: var(--accent-wash); color: var(--accent-deep);
  border-radius: 999px; padding: 3px 10px;
}
.pill-red { background: var(--red-wash); color: var(--red); }
.pill-amber { background: var(--amber-wash); color: var(--amber); }

/* reveal-on-scroll */
.reveal { opacity: 0; transform: translateY(22px); transition: opacity 0.6s ease, transform 0.6s ease; }
.reveal[data-delay="1"] { transition-delay: 0.12s; }
.reveal[data-delay="2"] { transition-delay: 0.24s; }
.reveal[data-delay="3"] { transition-delay: 0.36s; }
.reveal[data-delay="4"] { transition-delay: 0.48s; }
.reveal.in { opacity: 1; transform: none; }

/* --------------------------- terminals ----------------------------- */
.mech-dark { background: var(--term-bg); color: #eef1ea; border-top: none; }
.mech-dark .eyebrow { color: #7fd4ac; }
.mech-dark h2 { color: #f4f6ef; }
.mech-dark p, .mech-dark .mech-points { color: #a9b3a2; }
.mech-dark .mech-points strong, .mech-dark em { color: #e8ecdf; }
.mech-dark .btn-ghost { color: #eef1ea; border-color: #eef1ea; }
.mech-dark .btn-ghost:hover { background: rgba(255, 255, 255, 0.08); }
.btn-replay { margin-top: 1.6em; font-family: var(--mono); font-size: 0.85rem; padding: 9px 18px; cursor: pointer; }

.terminal {
  background: #0e110c; border: 1px solid #2a2f26; border-radius: var(--radius);
  overflow: hidden; box-shadow: 0 24px 60px -30px rgba(0, 0, 0, 0.55);
  font-family: var(--mono); font-size: 0.84rem;
}
.term-bar {
  display: flex; align-items: center; gap: 7px; padding: 11px 14px;
  background: #171b14; border-bottom: 1px solid #2a2f26;
}
.term-bar span { width: 10px; height: 10px; border-radius: 50%; background: #3a4034; }
.term-bar em { font-style: normal; color: #8b947f; font-size: 0.72rem; margin-left: 8px; }
.term-body { padding: 18px 18px 22px; display: grid; gap: 7px; }
.t-line { color: #d9e2d3; max-width: none; line-height: 1.5; overflow-wrap: anywhere; }
.t-dim { color: #79826d; }
.t-hook { color: #9ab8ff; }
.t-bad { color: #ff8d7a; }
.t-good { color: #74d99f; }
.t-tag {
  font-size: 0.64rem; text-transform: uppercase; letter-spacing: 0.1em;
  background: rgba(255, 141, 122, 0.15); color: #ff8d7a;
  border-radius: 4px; padding: 1px 6px; margin: 0 4px;
}
.terminal code, .terminal .mono {
  background: transparent; border: none; padding: 0;
  color: #7fd4ac; font-size: inherit;
}
#term-body .t-line { opacity: 0; transform: translateY(4px); transition: opacity 0.35s ease, transform 0.35s ease; }
#term-body .t-line.on { opacity: 1; transform: none; }

.terminal-light { box-shadow: 0 24px 60px -34px rgba(22, 24, 15, 0.5); }
.caret {
  display: inline-block; width: 8px; height: 1.05em; background: #74d99f;
  vertical-align: text-bottom; margin-left: 2px; animation: blink 1s steps(1) infinite;
}
@keyframes blink { 50% { opacity: 0; } }
.adopt-result { display: grid; gap: 7px; opacity: 0; transition: opacity 0.5s ease; }
.adopt-result.on { opacity: 1; }

/* --------------------------- fleet board --------------------------- */
.fleet-board {
  border: 1.5px solid var(--ink); border-radius: var(--radius); background: var(--paper);
  padding: 20px; box-shadow: 0 2px 0 var(--ink);
}
.canon-bar {
  display: flex; align-items: center; gap: 12px; padding: 10px 14px;
  background: var(--ink); color: var(--paper); border-radius: 10px;
  font-size: 0.9rem; position: relative; overflow: hidden;
}
.canon-bar .mono { background: none; border: none; color: var(--paper); }
.canon-bar .mono b { color: #7fd4ac; }
.clock { width: 26px; height: 26px; color: #7fd4ac; }
.clock-hand { transform-origin: 22px 22px; animation: sweep 8s linear infinite; }
@keyframes sweep { to { transform: rotate(360deg); } }
.canon-pulse {
  position: absolute; inset: 0; border-radius: 10px; pointer-events: none;
  background: linear-gradient(100deg, transparent 30%, rgba(127, 212, 172, 0.35) 50%, transparent 70%);
  transform: translateX(-100%);
}
.canon-pulse.go { animation: slide 1.2s ease-in-out; }
@keyframes slide { to { transform: translateX(100%); } }

.repo-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 14px; }
.repo-tile {
  border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
  font-family: var(--mono); font-size: 0.74rem; display: grid; gap: 3px;
  transition: border-color 0.35s ease, background 0.35s ease;
}
.repo-tile .r-name { font-weight: 700; color: var(--ink); }
.repo-tile .r-ref { color: var(--ink-soft); transition: color 0.35s ease; }
.repo-tile.stale .r-ref { color: var(--amber); }
.repo-tile.fresh { border-color: var(--accent); background: var(--accent-wash); }
.repo-tile.fresh .r-ref { color: var(--accent-deep); font-weight: 700; }
.fleet-board .viz-caption { margin-top: 12px; }

/* ------------------------------ cards ------------------------------ */
.band { padding: clamp(56px, 8vw, 104px) 0; border-top: 1px solid var(--line); }
.band-2 { background: var(--paper-2); }
.cards { list-style: none; display: flex; flex-wrap: wrap; gap: 16px; margin-top: 2em; }
.card {
  flex: 1 1 260px; background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 24px 24px 22px;
}
.card h3 { margin-bottom: 0.5em; }
.card p { font-size: 0.95rem; color: var(--ink-soft); max-width: none; }
.cards-tight .card { flex-basis: 230px; padding: 20px 22px 18px; }
.cards-tight .card h3 { font-size: 1.05rem; }
.cards-tight .card p { font-size: 0.9rem; }
.cards-dark { margin-top: clamp(40px, 5vw, 64px); }
.cards-dark .card { background: #1b1f19; border-color: #2a2f26; }
.cards-dark .card h3 { color: #7fd4ac; font-size: 1.05rem; }
.card h3 .big { display: block; font-size: 2.4rem; line-height: 1; margin-bottom: 4px; }
.cards-dark .card p { color: #a9b3a2; font-size: 0.92rem; }

/* ------------------------- canon stats + spotlight ----------------- */
.canon-now { margin-top: clamp(56px, 7vw, 88px); }
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin: 0 0 2em; }
.stat {
  background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px 22px;
}
.stat b { display: block; font-size: clamp(1.7rem, 3vw, 2.4rem); letter-spacing: -0.03em; line-height: 1.1; color: var(--accent-deep); }
.stat span { display: block; font-size: 0.82rem; line-height: 1.4; margin-top: 6px; color: var(--ink-soft); font-family: var(--mono); }

.spotlight { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
.spot {
  border: 1.5px solid var(--ink); border-radius: var(--radius); padding: 24px;
  background: var(--paper); box-shadow: 0 2px 0 var(--ink);
}
.spot:first-child { grid-column: 1 / -1; background: var(--ink); color: var(--paper); }
.spot:first-child p { color: #c9cfbf; }
.spot h3 { margin-bottom: 0.4em; }
.spot:first-child h3 { color: #7fd4ac; font-size: 1.4rem; }
.spot p { font-size: 0.94rem; color: var(--ink-soft); max-width: none; }

/* ------------------------------ adopt ------------------------------ */
.adopt { padding: clamp(56px, 8vw, 104px) 0; border-top: 1px solid var(--line); }
.adopt-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: clamp(32px, 5vw, 64px); align-items: start; }
.steps { margin: 1.5em 0 0 1.2em; display: grid; gap: 1em; color: var(--ink-soft); }
.steps li::marker { font-family: var(--mono); font-weight: 700; color: var(--accent-deep); }
.steps b { color: var(--ink); }
.assure { margin: 2em 0 0; list-style: none; display: grid; gap: 0.6em; font-size: 0.9rem; color: var(--ink-soft); }
.assure li { padding-left: 1.5em; position: relative; }
.assure li::before { content: "✓"; position: absolute; left: 0; color: var(--accent); font-weight: 700; }

/* ------------------------------- faq ------------------------------- */
.faq { padding: clamp(56px, 8vw, 104px) 0; border-top: 1px solid var(--line); background: var(--paper-2); }
.faq details { border-bottom: 1px solid var(--line); }
.faq details:first-of-type { border-top: 1px solid var(--line); margin-top: 2em; }
.faq summary {
  cursor: pointer; padding: 18px 36px 18px 4px; font-weight: 650; font-size: 1.02rem;
  list-style: none; position: relative;
}
.faq summary::-webkit-details-marker { display: none; }
.faq summary::after {
  content: "+"; position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
  font-family: var(--mono); font-size: 1.2rem; color: var(--accent-deep); transition: transform 0.2s ease;
}
.faq details[open] summary::after { transform: translateY(-50%) rotate(45deg); }
.faq details p { padding: 0 4px 20px; color: var(--ink-soft); max-width: 68ch; }

/* ------------------------------ footer ----------------------------- */
.footer { border-top: 1px solid var(--line); padding: 48px 0 32px; }
.footer-grid { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; flex-wrap: wrap; }
.brand-footer { font-size: 1.15rem; }
.footer-tag { font-family: var(--mono); font-size: 0.8rem; color: var(--ink-soft); margin-top: 8px; }
.footer-links { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-links a { color: var(--ink-soft); text-decoration: none; font-size: 0.9rem; }
.footer-links a:hover { color: var(--ink); }
.footer-meta {
  margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--line);
  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  font-size: 0.8rem; color: var(--ink-soft);
}
.footer-meta p { max-width: 72ch; }
/* The copyright carries the released version in its title tooltip. */
.copyright { cursor: help; }

/* ---------------------------- responsive --------------------------- */
@media (max-width: 940px) {
  .mech-grid, .adopt-grid { grid-template-columns: 1fr; }
  .mech-grid-flip > .mech-copy { order: 0; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .spotlight { grid-template-columns: 1fr; }
  .repo-grid { grid-template-columns: repeat(2, 1fr); }
  .nav nav a:not(.nav-cta) { display: none; }
}

/* SVG text scales with the viewBox, so on a narrow screen a figure's labels
   shrink below reading size. Enlarge them in user units where the drawing has
   room; hide the two that do not. */
@media (max-width: 720px) {
  .gates, .flow-fig { display: none; }
  .bf-q { font-size: 18px; }
  .bf-note { font-size: 16px; }
  .bf-stamp text { font-size: 14px; }
  .gr-node text { font-size: 20px; }
  .gr-center { font-size: 17px; }
  .ladder { padding-right: 56px; }
  .rung { grid-template-columns: 1fr; row-gap: 2px; padding-left: calc(1.3rem * var(--n) + 2.2rem); min-height: 72px; }
  .rung-tread { width: calc(1.3rem * var(--n) + 1.4rem); }
}
@media (max-width: 480px) {
  .repo-grid { grid-template-columns: repeat(2, 1fr); }
  .stats { grid-template-columns: 1fr 1fr; }
}

/* -------------------------- reduced motion ------------------------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal, #term-body .t-line { opacity: 1; transform: none; transition: none; }
  .adopt-result { opacity: 1; }
  .caret, .clock-hand, .gr-pulse, .canon-pulse, .bf-stamp { animation: none !important; }
  .gt-chip, .gt-tag, .gt-landed, .gt-lamp, .gt-chip rect, .gt-chip path,
  .bf-floor, .token, .meter-fill, .rung-tread, .btn { transition: none !important; }
  .gr-pulse { stroke-dasharray: none; stroke: none; }
}

/* ---------- Legal pages (privacy) ---------- */
.legal { padding: 72px 0 40px; }
.legal-title { font-size: clamp(2.2rem, 5vw, 3.4rem); margin-bottom: 0.4em; }
.legal-lede { font-size: 1.15rem; color: var(--ink-soft); margin-bottom: 1.6em; }
.legal p { margin-bottom: 1.1em; }
.legal h2 { font-size: clamp(1.3rem, 2.4vw, 1.7rem); margin: 1.8em 0 0.5em; }
.legal a { color: var(--accent-deep); }

